nologinflag = /<div\s*class="title"\s*>.*1234.*/.test(result.body());
java.log("登录检测,需要验证："+nologinflag)
if (nologinflag) {
	url = String(baseUrl + "," + JSON.stringify({
		"charset": "gbk",
		"method": "POST",
		"body": "action=1&v=1234"
	}));
	loginres = java.ajax(url);
	//if(loginres=="success") nologinflag = loginres
	//java.toast("自动验证："+nologinflag);
	result = java.getStrResponse();
	java.log("自动验证&重新获取："+nologinflag);
}
result

