for (let i in result) {
	result[i] = String(result[i]).replace(/.+?\('\d+','\d+','(\d+)','(\d+)'\).+?/, (str, p1, p2) => p1 + '_' + p2 + '.html');
}
result

ruleToc.nextTocUrl:
.endPage@href##_(\d+)/##$1###
<js>
maxPage = result[0];
urls = [];
url = baseUrl.replace(/(_\d+)?\/?$/, '_');
for (i = 2; i <= maxPage; i++) urls.push(url + i + '/');
urls
</js>

